// KEV catalog fetched once at workflow start
const kevRaw = $('HTTP Fetch CISA KEV').first().json;
const kevSet = new Set(
  ((kevRaw && kevRaw.vulnerabilities) || []).map(v => v.cveID)
);

// Original AV rows — same order as Shodan responses
const avItems  = $('Postgres Query Applicable').all().map(i => i.json);
const shodanItems = $input.all();

if (!avItems.length) return [];

const results = [];

for (let i = 0; i < avItems.length; i++) {
  const av     = avItems[i];
  const shRaw  = shodanItems[i] ? shodanItems[i].json : null;

  // Shodan exposed: response must have ip_str (successful lookup)
  // 404 / error / null-IP sentinel → not exposed
  const shodanExposed = !!(shRaw && shRaw.ip_str && !shRaw.error);

  // KEV
  const kevListed = kevSet.has(av.cve_id_str);

  // CVSS base — v3 preferred; treat missing as 0
  const cvssBase = parseFloat(av.cvss_v3_base_score) || 0;

  // CVSS temporal: exploit_available → High multiplier (1.0), else Unproven (0.90)
  const exploitMultiplier = av.exploit_available ? 1.0 : 0.90;
  const cvssTemp = cvssBase * exploitMultiplier;

  // Exposure factor — spec: Shodan visible=10, not visible=3
  const exposureFactor = shodanExposed ? 10 : 3;

  // Criticality factor from asset tier
  const critMap = { CRITICAL: 10, HIGH: 7.5, MEDIUM: 5, LOW: 2.5 };
  const critFactor = critMap[av.criticality] || 5;

  // KEV bonus
  const kevBonus = kevListed ? 2.0 : 0;

  // Risk score formula (spec §2.4)
  let riskScore = (0.35 * cvssBase)
               + (0.25 * cvssTemp)
               + (0.20 * exposureFactor)
               + (0.15 * critFactor)
               + kevBonus;

  // Cap at 10.0, round to 2 decimals
  riskScore = Math.round(Math.min(10.0, riskScore) * 100) / 100;

  // Criticality tier thresholds (spec §2.4)
  let criticalityTier;
  if      (riskScore >= 8.5) criticalityTier = 'CRITICAL';
  else if (riskScore >= 7.0) criticalityTier = 'HIGH';
  else if (riskScore >= 5.0) criticalityTier = 'MEDIUM';
  else                       criticalityTier = 'LOW';

  results.push({
    json: {
      av_id:             av.av_id,
      cve_db_id:         av.cve_db_id,
      risk_score:        riskScore,
      criticality_tier:  criticalityTier,
      shodan_exposed:    shodanExposed,
      kev_listed:        kevListed,
      exploit_available: av.exploit_available || false
    }
  });
}

return results;

const updated  = $input.all();
const avItems  = $('Postgres Query Applicable').all().map(i => i.json);

// Unique CVE DB IDs (FK to cves.id) — deduplicated, for status UPDATE
const cveDbIds = [...new Set(avItems.map(i => i.cve_db_id))].join(',');

return [{
  json: {
    recordsProcessed: updated.length,
    cveDbIds
  }
}];
